-- Paket ABT "abt-romawi-pihak-28okt" (28 Okt 2026): angka romawi pihak pada sampul pihak banyak (variabel 5847, 5890, 5891, 5892, 5893, 5896, 5897) dihitung dari PERINGKAT pihak dalam tabelnya, bukan dari nilai kolom `urutan` (perkara e-Court menomori urutan bersambung lintas tabel).
-- 7 baris variabel diubah; TIDAK ada fungsi baru (memakai isian_rtf_pihak_peringkat dari paket abt-pihak-urut-sisa-28okt dan isian_rtf_romawi yang sudah ada). Prasyarat: paket abt-pihak-urut-ecourt-27okt dan abt-pihak-urut-sisa-28okt sudah terpasang.
-- UJIVAR-LAMA: kueri lama tiap variabel diubah, dijalankan pasang-satker.sh atas perkara contoh (@pid diisi skrip). Keluaran "no_var<TAB>data" (0 baris bila kueri tak menghasilkan baris).
SELECT 5847 AS no_var, u.data FROM (SELECT CONCAT('INTERVENSI (',COUNT(*),') ',GROUP_CONCAT(CASE WHEN a.urutan<=3 THEN CONCAT(ELT(a.urutan,'I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX'),'. ',a.nama) END ORDER BY a.urutan SEPARATOR ' - '),IF(COUNT(*)>3,CONCAT(' - dan ',COUNT(*)-3,' lainnya (lampiran)'),'')) AS data FROM perkara_pihak3 a WHERE a.perkara_id=@pid HAVING COUNT(*)>0) AS u;
SELECT 5890 AS no_var, u.data FROM (SELECT GROUP_CONCAT(CONCAT(ELT(a.urutan,'I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX'),'. ',a.nama) ORDER BY a.urutan SEPARATOR '<br>') AS data FROM perkara_pihak1 a WHERE a.perkara_id=@pid AND a.urutan BETWEEN 2 AND 1+CEIL(IF((SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid)>IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12),IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12)-2,(SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid)-1)/2)) AS u;
SELECT 5891 AS no_var, u.data FROM (SELECT CONCAT_WS('<br>',(SELECT GROUP_CONCAT(CONCAT(ELT(a.urutan,'I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX'),'. ',a.nama) ORDER BY a.urutan SEPARATOR '<br>') FROM perkara_pihak1 a WHERE a.perkara_id=@pid AND a.urutan BETWEEN 2+CEIL(IF((SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid)>IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12),IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12)-2,(SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid)-1)/2) AND 1+IF((SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid)>IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12),IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12)-2,(SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid)-1)),IF((SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid)>IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12),CONCAT('dan ',(SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid)-IF((SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid)>IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12),IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12)-2,(SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid)-1)-1,' lainnya - lengkap di Lampiran Daftar Para Pihak'),NULL)) AS data) AS u;
SELECT 5892 AS no_var, u.data FROM (SELECT GROUP_CONCAT(CONCAT(ELT(a.urutan,'I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX'),'. ',a.nama) ORDER BY a.urutan SEPARATOR '<br>') AS data FROM perkara_pihak2 a WHERE a.perkara_id=@pid AND a.urutan BETWEEN 2 AND 1+CEIL(IF((SELECT COUNT(*) FROM perkara_pihak2 WHERE perkara_id=@pid)>IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12),IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12)-2,(SELECT COUNT(*) FROM perkara_pihak2 WHERE perkara_id=@pid)-1)/2)) AS u;
SELECT 5893 AS no_var, u.data FROM (SELECT CONCAT_WS('<br>',(SELECT GROUP_CONCAT(CONCAT(ELT(a.urutan,'I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX'),'. ',a.nama) ORDER BY a.urutan SEPARATOR '<br>') FROM perkara_pihak2 a WHERE a.perkara_id=@pid AND a.urutan BETWEEN 2+CEIL(IF((SELECT COUNT(*) FROM perkara_pihak2 WHERE perkara_id=@pid)>IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12),IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12)-2,(SELECT COUNT(*) FROM perkara_pihak2 WHERE perkara_id=@pid)-1)/2) AND 1+IF((SELECT COUNT(*) FROM perkara_pihak2 WHERE perkara_id=@pid)>IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12),IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12)-2,(SELECT COUNT(*) FROM perkara_pihak2 WHERE perkara_id=@pid)-1)),IF((SELECT COUNT(*) FROM perkara_pihak2 WHERE perkara_id=@pid)>IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12),CONCAT('dan ',(SELECT COUNT(*) FROM perkara_pihak2 WHERE perkara_id=@pid)-IF((SELECT COUNT(*) FROM perkara_pihak2 WHERE perkara_id=@pid)>IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12),IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1,8,12)-2,(SELECT COUNT(*) FROM perkara_pihak2 WHERE perkara_id=@pid)-1)-1,' lainnya - lengkap di Lampiran Daftar Para Pihak'),NULL)) AS data) AS u;
SELECT 5896 AS no_var, u.data FROM (SELECT IF((SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid)>1 AND EXISTS(SELECT 1 FROM perkara_pengacara WHERE perkara_id=@pid AND pihak_ke=1 AND aktif='Y'),CONCAT('(untuk ',IF((SELECT IF(p0.nomor_perkara LIKE '%/Pdt.G%',1,0) FROM perkara p0 WHERE p0.perkara_id=@pid)=1 AND (SELECT jenis_perkara_id FROM perkara WHERE perkara_id=@pid)<>346,'Penggugat','Pemohon'),' I-',ELT(LEAST((SELECT COUNT(*) FROM perkara_pihak1 WHERE perkara_id=@pid),20),'I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX'),')'),'') AS data) AS u;
SELECT 5897 AS no_var, u.data FROM (SELECT CONCAT('TURUT TERGUGAT (',COUNT(*),') ',GROUP_CONCAT(CASE WHEN a.urutan<=3 THEN CONCAT(ELT(a.urutan,'I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX'),'. ',a.nama) END ORDER BY a.urutan SEPARATOR ' - '),IF(COUNT(*)>3,CONCAT(' - dan ',COUNT(*)-3,' lainnya (lampiran)'),'')) AS data FROM perkara_pihak4 a WHERE a.perkara_id=@pid HAVING COUNT(*)>0) AS u;
